[
  {
    "slot_number": "slot-6-1-1",
    "slot_key": "Inbound tasking messages",
    "slot_value": "Tasking information for one consistent way to plan, task, and control missions across UAV platforms; supports changing tasking and quick mission updates",
    "operation": "update"
  },
  {
    "slot_number": "slot-6-1-2",
    "slot_key": "Outbound status and execution updates",
    "slot_value": "Operational information, including launch-to-recovery status visibility, payload management, sensor monitoring, imagery and other mission products distribution, and feedback into the broader command-and-control environment; first operational outcomes include reliable mission planning, real-time control and monitoring, payload and sensor handling, and getting mission products into the wider command-and-control flow; response must happen within the window where the aircraft is still safe and the mission can still be recovered; operator or commander needs the right aircraft state, payload state, and mission context to make the decision without guessing; in degraded communications, the essentials for keeping the aircraft safe are basic aircraft status, link status, location, fuel or endurance, major faults, and payload state if it affects flight or safety; detailed health trends, full sensor housekeeping, and non-urgent mission logs can be queued and sent later; anything indicating imminent loss of vehicle, loss of control, or a critical subsystem failure should be able to trigger an automatic safeguard or mission pause even if nobody can respond right away; the system should support controlled release, auditing, and metadata marking so that when products are handed off, only the approved content and context go with them; after release, the receiving system should acknowledge receipt, preserve markings and context, and use the information for tasking, situational awareness, or product dissemination as authorized; the exchange is meant to keep the tactical picture aligned across systems and support mission execution, targeting support where approved, and timely distribution of imagery or other mission products.",
    "operation": "update"
  },
  {
    "slot_number": "slot-6-1-3",
    "slot_key": "Tasking acknowledgement and conflict handling",
    "slot_value": "Hand-off between operators or control stations needs to be very clean during preplanned surveillance, time-sensitive retask, degraded communications, lost-link recovery, and while payload tasking changes in flight; especially important for safety interventions, control handoffs, target or sensor retasking, and anything affecting airspace deconfliction or mission authorization because wrong or delayed action can have immediate consequences. The controlling station may change, and authority needs to move cleanly with the aircraft so there’s no ambiguity about who can command it. Allowed actions may differ by setup, with some stations only monitoring while others can fully command, including coalition operations and reach-back support. Current mission plans should not be overwritten without review; new tasking should be preserved as a change or re-tasking request for operator assessment, with possible merge, queue, or transition to a new profile. If the new tasking requires a different payload setup or control source, the handoff must be explicit so the system does not lose track of what is flying, who owns it, or which mission objective is current.",
    "operation": "update"
  },
  {
    "slot_number": "slot-6-1-dyn-4",
    "slot_key": "Mission-specific tasking and handoff behavior",
    "slot_value": "For preplanned surveillance, the system should be conservative and keep the approved route and payload setup unless an operator explicitly authorizes a change. Any change that affects where the aircraft goes, what the sensor is looking at, when it collects, or how it behaves should require explicit operator authorization before execution. Small background updates, like display-only status changes or non-operative metadata, should not need that level of approval. If the change could alter collection, safety, or coordination with other forces, the system should stop and ask for a clear human confirmation first.",
    "operation": "update"
  },
  {
    "slot_number": "slot-6-1-dyn-5",
    "slot_key": "Common mission object vocabulary",
    "slot_value": "Standard shared meanings for mission, task, route, waypoint, target, payload, and product so operators, planners, and downstream users interpret them the same way; the core vocabulary should be defined now at a working level because ambiguity across programs will cause problems, while platform-specific specialized terms can be added later; edge cases or new concepts not yet seen should remain tentative until confirmed with users and platform teams",
    "operation": "update"
  },
  {
    "slot_number": "slot-6-1-dyn-6",
    "slot_key": "Standard mission status terms",
    "slot_value": "Common definitions for planned, executing, complete, aborted, and degraded status terms to support operator decisions and handoffs; the core mission and status terms should mean the same thing everywhere the common system is used, at least at a working level, while edge cases or new concepts can remain tentative until confirmed with users and platform teams",
    "operation": "update"
  },
  {
    "slot_number": "slot-6-1-dyn-7",
    "slot_key": "Connection state and station role handling",
    "slot_value": "Support intermittent links, delayed updates, and a clear state showing whether a station is local, remote, primary, or backup. Handoff state should also be visible, indicating when the aircraft is in transition.",
    "operation": "update"
  },
  {
    "slot_number": "slot-6-1-dyn-8",
    "slot_key": "Ground station state labels",
    "slot_value": "Current authority, standby, and in-transition",
    "operation": "update"
  },
  {
    "slot_number": "slot-6-1-dyn-9",
    "slot_key": "Authority transfer rules",
    "slot_value": "A station may be monitor-only when it lacks current authority, the link is too limited for safe command, or policy restricts command because of mission sensitivity, certification, or airspace constraints. It may command the aircraft when it has assigned control authority, the communications path is good enough, and the operator is cleared for that mission segment. Authority can change during the mission, especially during handoff between sites or if the primary station loses connectivity and a backup takes over.",
    "operation": "update"
  },
  {
    "slot_number": "slot-6-1-dyn-10",
    "slot_key": "Handoff completion indicators",
    "slot_value": "Clean acknowledgment from both outgoing and incoming controllers; if handoff is incomplete or the link is unstable, hold the aircraft in a safe interim state and retain last confirmed authority until transfer is resolved",
    "operation": "update"
  },
  {
    "slot_number": "slot-6-1-dyn-11",
    "slot_key": "Retasking review workflow",
    "slot_value": "When a re-tasking request arrives, route it through operator review first with enough context to judge whether it conflicts with the active mission, current authority, or flight and payload constraints. If the request is just informational or still under review, keep it separate from the live mission. If it is compatible with the current route, payload, timing, and authority, it can be linked or merged so the operator can apply it without rebuilding the mission from scratch. If it is related but not yet approved, show it alongside the live mission as a candidate change so the controller can compare them without any risk of accidentally executing it. If the retask fits within the current authority and doesn’t conflict with a critical phase of flight or collection, accept it quickly and immediately assess what it would displace. If the displacement is significant or could create a safety or mission conflict, hold it for review rather than auto-applying.",
    "operation": "update"
  },
  {
    "slot_number": "slot-6-1-dyn-12",
    "slot_key": "Merge versus queue decision rules",
    "slot_value": "Low-risk requests within current authority can be accepted or queued quickly; if the request changes mission objective, route, payload behavior, collection, safety, or coordination with other forces in a meaningful way, it should require explicit approval before being merged. If the request is just informational or still under review, it should stay separate from the live mission. If it is compatible with the current route, payload, timing, and authority, it can be linked or merged. If it is related but not yet approved, it should be shown alongside the live mission as a candidate change for comparison without accidental execution. If the retask fits within the current authority and doesn’t conflict with a critical phase of flight or collection, accept it quickly and immediately assess what it would displace. If the displacement is significant or could create a safety or mission conflict, hold it for review rather than auto-applying.",
    "operation": "update"
  },
  {
    "slot_number": "slot-6-1-dyn-13",
    "slot_key": "Transition to new mission profile criteria",
    "slot_value": "A new mission profile is required when the re-tasking meaningfully changes the mission objective, route, or payload behavior.",
    "operation": "update"
  },
  {
    "slot_number": "slot-6-1-dyn-14",
    "slot_key": "Current mission ownership indicator",
    "slot_value": "The active mission should be shown as owned by the current controlling station or unit, while a new tasking should be shown separately as a pending proposal or external request until approved and applied; when products are handed off, only approved content and context should go with them",
    "operation": "update"
  },
  {
    "slot_number": "slot-6-1-dyn-15",
    "slot_key": "Active objective selection",
    "slot_value": "The original mission remains in force until the change is approved and applied; queued requests must stay visibly separate from the live mission state until authorized.",
    "operation": "update"
  },
  {
    "slot_number": "slot-6-1-dyn-16",
    "slot_key": "Control source handoff confirmation",
    "slot_value": "Require a clean acknowledgment from both the outgoing and incoming controllers before command authority transfers",
    "operation": "update"
  },
  {
    "slot_number": "slot-6-1-dyn-17",
    "slot_key": "Raw sensor data protection versus processed products",
    "slot_value": "Raw sensor data should be protected more tightly than processed products because raw data may expose sources, methods, or details not meant for broad distribution; forwarding and repackaging should be limited to users or systems with the right role and release authority, each handoff should preserve the original markings and handling caveats, and processed products may often be shared instead of raw data when that still meets the tasking need and protects sensitive collection details.",
    "operation": "update"
  },
  {
    "slot_number": "slot-6-1-dyn-18",
    "slot_key": "Controlled release auditing and metadata marking",
    "slot_value": "Sharing and handoff should support controlled release, auditing, and metadata marking; when raw sensor data is released, it should be governed by classification, releasability, mission authority, and recipient approval for that specific data set. If any of those checks fail, the raw data should not be released at all. When released, sensitive collection details and operator identity should be stripped, only the minimum technical metadata needed to interpret the data should be retained, and the data should be marked with proper caveats, origin, time, and handling instructions so the context remains clear but controlled. The system should also log who touched the data, when, and what changed to preserve traceability in the wider command-and-control environment.",
    "operation": "update"
  }
